    {activeTab!=='purchases'&&activeTab!=='requests'&&activeTab!=='purchase-quotes'&&activeTab!=='purchase-invoices'&&activeTab!=='purchase-receipts'&&activeTab!=='purchase-invoice-entry'&&activeTab!=='purchase-invoice-drafts'&&activeTab!=='deliveries'&&<><SalesListToolbar activeTab={activeTab as 'quotes'|'orders'|'invoices'} total={salesListTotal} loading={loading} search={search} onSearchChange={setSearch}/></>}

