  const [loading,setLoading]=useState(true),[error,setError]=useState(''),[invoiceId,setInvoiceId]=useState<string|null>(null),[warehouses,setWarehouses]=useState<Warehouse[]>([])
  const defaultLayout:BuiltInScreenLayoutField[]=[{key:'code',label:'Fatura no',visible:true,position:0},{key:'supplierName',label:'Tedarikçi',visible:true,position:1},{key:'receiptCode',label:'Mal kabul',visible:true,position:2},{key:'purchaseOrderCode',label:'Sipariş no',visible:true,position:3},{key:'invoiceDate',label:'Fatura tarihi',visible:true,position:4},{key:'dueDate',label:'Vade tarihi',visible:true,position:5},{key:'currencyCode',label:'Döviz',visible:true,position:6},{key:'grandTotal',label:'Toplam',visible:true,position:7},{key:'paidAmount',label:'Ödenen',visible:true,position:8},{key:'outstandingAmount',label:'Ödenmemiş',visible:true,position:9},{key:'lineCount',label:'Satır',visible:true,position:10},{key:'status',label:'Durum',visible:true,position:11},{key:'actions',label:'İşlemler',visible:true,position:12,fixed:true}]
  const [screenFields,setScreenFields]=useState(defaultLayout)
  const pageSize=25
  async function load(){setLoading(true);setError('');try{const params=new URLSearchParams({page:String(page),pageSize:String(pageSize),q:query.trim()});if(supplierFilter)params.set('supplierId',supplierFilter.id);const result=await api<{items:PurchaseInvoiceSummary[];page:number;pageSize:number;totalCount:number}>(`/api/purchasing/invoices/?${params}`,token);setItems(result.items);setTotal(result.totalCount)}catch(e){setError((e as Error).message)}finally{setLoading(false)}}
  useEffect(()=>{void load()},[token,page,query,supplierFilter?.id])
  useEffect(()=>{if(initialSupplier)onInitialSupplierOpened?.()},[initialSupplier,onInitialSupplierOpened])
  useEffect(()=>{let cancelled=false;api<{fields:BuiltInScreenLayoutField[]}>('/api/screen-views/purchase-invoices/active',token).then(view=>{if(!cancelled&&view.fields?.length)setScreenFields(view.fields)}).catch(()=>{});return()=>{cancelled=true}},[token])
