  function renderPurchaseOrderField(field:BuiltInScreenLayoutField,item:PurchaseOrderSummary){
    switch(field.key){
      case 'code': return <span className="customer-code">{item.code}</span>
      case 'supplierName': return <b className="customer-name">{item.supplierName}</b>
      case 'orderDate': return item.orderDate.split('-').reverse().join('.')
      case 'expectedReceiptDate': return item.expectedReceiptDate?.split('-').reverse().join('.')||'—'
      case 'targetWarehouseCode': return warehouses.find(warehouse=>warehouse.id===item.targetWarehouseId)?.code||'—'
      case 'lineCount': return item.lineCount
      case 'grandTotal': return <b>{item.grandTotal.toLocaleString('tr-TR',{minimumFractionDigits:2})}</b>
      case 'currencyCode': return item.currencyCode
      case 'status': return <span className={`quote-status ${item.status==='Received'?'accepted':item.status==='Cancelled'?'rejected':'sent'}`}>{item.status==='Open'?'Açık':item.status==='PartiallyReceived'?'Kısmi mal kabul':item.status==='Received'?'Tam alındı':'İptal'}</span>
      case 'actions': return <button className="row-action" onClick={()=>void openOrder(item.id)}>Detay / Mal kabul</button>
      default: return null
    }
  }
