function SalesOrderModal({order,token,role,warehouses,onClose,onSaved,onInvoiceCreated}:{order:SalesOrderDetail;token:string;role:string;warehouses:Warehouse[];onClose:()=>void;onSaved:()=>Promise<void>;onInvoiceCreated:(id:string)=>void}) {
  const defaultOrderLineFields:BuiltInScreenLayoutField[]=[{key:'stockCode',label:'Stok kodu',visible:true,position:0},{key:'stockName',label:'Stok adı',visible:true,position:1},{key:'quantity',label:'Sipariş miktarı',visible:true,position:2},{key:'deliveredQuantity',label:'Teslim edilen',visible:true,position:3},{key:'remainingQuantity',label:'Kalan miktar',visible:true,position:4},{key:'reservedQuantity',label:'Rezerve',visible:true,position:5},{key:'unitPrice',label:'Birim fiyat',visible:true,position:6},{key:'lineTotal',label:'Satır toplamı',visible:true,position:7}]
  const [orderLineFields,setOrderLineFields]=useState<BuiltInScreenLayoutField[]>(defaultOrderLineFields)
  const visibleOrderLineFields=orderLineFields.filter(field=>field.visible).sort((a,b)=>a.position-b.position)
  const [deliveries,setDeliveries]=useState<SalesDeliverySummary[]>([]),[loading,setLoading]=useState(true),[busy,setBusy]=useState(false)
  const [error,setError]=useState(''),[notice,setNotice]=useState(''),[editor,setEditor]=useState(false)
  const [customFieldValues,setCustomFieldValues]=useState<Record<string,string>>(()=>Object.fromEntries((order.customFields||[]).map(field=>[field.code,field.value])))
  const [requestedDeliveryDate,setRequestedDeliveryDate]=useState(order.requestedDeliveryDate||'')
  const [warehouseId,setWarehouseId]=useState(warehouses[0]?.id||''),[deliveryDate,setDeliveryDate]=useState(localDateString())
  const [requestId,setRequestId]=useState(()=>crypto.randomUUID())
  const [reservationEditor,setReservationEditor]=useState(false),[reservationWarehouseId,setReservationWarehouseId]=useState(warehouses.find(x=>x.isActive)?.id||''),[reservationRequestId,setReservationRequestId]=useState(()=>crypto.randomUUID())
  const [quantities,setQuantities]=useState<Record<number,string>>(()=>Object.fromEntries(order.lines.map(x=>[x.lineNumber,String(x.remainingQuantity)])))
  const [deliveryUnits,setDeliveryUnits]=useState<Record<number,StockItemUnitConversion[]>>({}),[enteredDeliveryUnits,setEnteredDeliveryUnits]=useState<Record<number,string>>(()=>Object.fromEntries(order.lines.map(x=>[x.lineNumber,x.unitCode]))), [deliveryLocations,setDeliveryLocations]=useState<WarehouseLocationOption[]>([]),[deliveryLocationIds,setDeliveryLocationIds]=useState<Record<number,string>>({})
  async function loadDeliveries(){setLoading(true);try{const page=await api<{items:SalesDeliverySummary[]}>(`/api/sales/deliveries/?orderId=${order.id}&page=1&pageSize=100`,token);setDeliveries(page.items)}catch(e){setError((e as Error).message)}finally{setLoading(false)}}
  useEffect(()=>{void loadDeliveries()},[order.id,token])
  useEffect(()=>{let active=true;void api<{fields:BuiltInScreenLayoutField[]}>('/api/screen-views/sales-order-lines/active',token).then(view=>{if(active&&view.fields?.length)setOrderLineFields(view.fields)}).catch(()=>{});return()=>{active=false}},[token])
  useEffect(()=>{setCustomFieldValues(Object.fromEntries((order.customFields||[]).map(field=>[field.code,field.value])))},[order.id,order.customFields])
  useEffect(()=>{setRequestedDeliveryDate(order.requestedDeliveryDate||'')},[order.id,order.requestedDeliveryDate])
  async function saveRequestedDeliveryDate(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');setNotice('');try{await api<SalesOrderSummary>(`/api/sales/orders/${order.id}/delivery-date`,token,{method:'PUT',body:JSON.stringify({requestedDeliveryDate:requestedDeliveryDate||null})});setNotice('İstenen teslim tarihi güncellendi. MRP bu tarihi ihtiyaç tarihi olarak kullanacak.');await onSaved()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
  async function saveOrderCustomFields(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');setNotice('');try{await api<SalesOrderCustomFieldValue[]>(`/api/sales/orders/${order.id}/custom-fields`,token,{method:'PUT',body:JSON.stringify({values:customFieldValues})});setNotice('Satış siparişi özel alanları kaydedildi.');await onSaved()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
  async function loadDeliveryLocations(targetWarehouseId:string){if(!targetWarehouseId){setDeliveryLocations([]);return}try{setDeliveryLocations((await api<WarehouseLocationOption[]>(`/api/warehouses/${targetWarehouseId}/locations`,token)).filter(location=>location.isActive))}catch(e){setError((e as Error).message)}}
  async function startDelivery(){setError('');setNotice('');setRequestId(crypto.randomUUID());const targetWarehouseId=order.lines.find(x=>x.reservationId)?.reservationWarehouseId||warehouses.find(x=>x.isActive)?.id||'';setWarehouseId(targetWarehouseId);setDeliveryLocationIds({});void loadDeliveryLocations(targetWarehouseId);setQuantities(Object.fromEntries(order.lines.map(x=>[x.lineNumber,String(x.reservationId?Math.min(x.remainingQuantity,x.reservedQuantity):x.remainingQuantity)])));setEnteredDeliveryUnits(Object.fromEntries(order.lines.map(x=>[x.lineNumber,x.unitCode])));try{const units=await Promise.all(order.lines.map(async line=>{const result=await api<{conversions:StockItemUnitConversion[]}>(`/api/stock/items/${line.stockItemId}/units`,token);return [line.lineNumber,result.conversions] as const}));setDeliveryUnits(Object.fromEntries(units))}catch(e){setError((e as Error).message);return}setEditor(true)}
  async function reserveOrderStock(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');setNotice('');try{await api(`/api/sales/orders/${order.id}/reservations`,token,{method:'POST',body:JSON.stringify({requestId:reservationRequestId,warehouseId:reservationWarehouseId})});setReservationRequestId(crypto.randomUUID());setReservationEditor(false);setNotice('Açık satış siparişi miktarları depoda rezerve edildi.');await onSaved()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
  async function releaseOrderReservation(){const reason=window.prompt('Rezervasyonu bırakma gerekçesi:')?.trim();if(!reason)return;if(!window.confirm('Siparişin kalan stok rezervasyonu bırakılsın mı?'))return;setBusy(true);setError('');setNotice('');try{await api(`/api/sales/orders/${order.id}/reservations/release`,token,{method:'POST',body:JSON.stringify({reason,confirmation:true})});setNotice('Kalan stok rezervasyonu bırakıldı ve kullanılabilir bakiyeye döndü.');await onSaved()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
  async function createDelivery(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');setNotice('');const lines=order.lines.map(x=>({orderLineNumber:x.lineNumber,quantity:Number(quantities[x.lineNumber]||0),unitCode:enteredDeliveryUnits[x.lineNumber]||x.unitCode,storageLocationId:deliveryLocationIds[x.lineNumber]||null})).filter(x=>x.quantity>0);try{if(!lines.length)throw new Error('En az bir satır için teslim miktarı girin.');await api<SalesDeliverySummary>(`/api/sales/orders/${order.id}/deliveries`,token,{method:'POST',body:JSON.stringify({requestId,warehouseId,deliveryDate,lines})});setNotice('İrsaliye oluşturuldu ve stok çıkışı kaydedildi.');setEditor(false);await onSaved();await loadDeliveries()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
  async function createInvoice(item:SalesDeliverySummary){setBusy(true);setError('');setNotice('');try{const invoice=await api<SalesInvoiceSummary>(`/api/sales/deliveries/${item.id}/invoice`,token,{method:'POST'});setNotice('Satış faturası ve cari borç kaydı oluşturuldu.');await onSaved();await loadDeliveries();onInvoiceCreated(invoice.id)}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
  async function voidDelivery(item:SalesDeliverySummary){if(!window.confirm(`${item.code} irsaliyesi iptal edilsin mi? Stok hareketi ters kaydedilecek.`))return;setBusy(true);setError('');setNotice('');try{await api(`/api/sales/deliveries/${item.id}/void`,token,{method:'POST'});setNotice('İrsaliye iptal edildi; stok kaydı ters hareketle korundu.');await onSaved();await loadDeliveries()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
  const activeReservation=order.lines.some(x=>x.reservationId!==null)
  return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><div className="modal ledger-modal sales-detail-modal" role="dialog" aria-modal="true" aria-labelledby="sales-order-detail-title"><div className="modal-head"><div><p className="eyebrow">{order.code} · SATIŞ SİPARİŞİ</p><h2 id="sales-order-detail-title">{order.customerName}</h2></div><button type="button" className="icon-button" aria-label="Sipariş ayrıntısını kapat" onClick={onClose}><X size={19}/></button></div>
    {error&&<div className="alert inline-alert">{error}<button onClick={()=>setError('')}><X size={15}/></button></div>}{notice&&<div className="notice">{notice}<button onClick={()=>setNotice('')}><X size={15}/></button></div>}
    <div className="balance-banner"><div><small>{order.quoteCode} teklifinden · {order.currencyCode}</small><b>{order.grandTotal.toLocaleString('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2})} {order.currencyCode}</b><span>Ara toplam {order.subtotal.toLocaleString('tr-TR',{minimumFractionDigits:2})} · İskonto {order.discountTotal.toLocaleString('tr-TR',{minimumFractionDigits:2})} · KDV {order.taxTotal.toLocaleString('tr-TR',{minimumFractionDigits:2})}</span></div><span className={`quote-status ${order.status==='Fulfilled'?'accepted':'sent'}`}>{order.status==='Fulfilled'?'Tamamlandı':order.status==='Cancelled'?'İptal':'Açık'}</span></div>
    {order.status==='Open'&&<form className="panel" style={{marginTop:14}} onSubmit={saveRequestedDeliveryDate}><div className="form-two"><label>İstenen teslim tarihi <span className="optional-label">İsteğe bağlı</span><input type="date" min={order.orderDate} value={requestedDeliveryDate} onChange={e=>setRequestedDeliveryDate(e.target.value)}/></label><div><small>MRP, açık sipariş talebini bu tarihte karşılamaya çalışır.</small><button className="secondary" disabled={busy}>Teslim tarihini kaydet</button></div></div></form>}
    {order.customFields?.length>0&&<form onSubmit={saveOrderCustomFields} className="panel" style={{marginTop:14}}><div className="panel-heading"><div><b>Sipariş özel alanları</b><small>{order.status==='Open'?'Açık siparişte düzenlenebilir.':'Sipariş kapanınca kilitlenir.'}</small></div></div><div className="form-two">{order.customFields.map(field=><label key={field.definitionId}>{field.label}{field.isRequired?' *':''}<small>{field.code} · {field.dataType}</small>{order.status!=='Open'?<span>{field.value||'—'}</span>:field.dataType==='Boolean'?<select required={field.isRequired} value={customFieldValues[field.code]||''} onChange={e=>setCustomFieldValues(current=>({...current,[field.code]:e.target.value}))}><option value="">Seçin</option><option value="true">Evet</option><option value="false">Hayır</option></select>:<input type={field.dataType==='Decimal'?'number':field.dataType==='Date'?'date':'text'} step={field.dataType==='Decimal'?'any':undefined} maxLength={field.dataType==='Text'?field.maxLength:undefined} required={field.isRequired} disabled={order.status!=='Open'} value={customFieldValues[field.code]||''} onChange={e=>setCustomFieldValues(current=>({...current,[field.code]:e.target.value}))}/>}</label>)}</div>{order.status==='Open'&&<div className="modal-foot"><span>Tekliften eşleşen kodlu alan değerleri taşındı.</span><button className="primary" disabled={busy}>Değerleri kaydet</button></div>}</form>}
     <div className="ledger-list"><AdvancedDataGrid className="customer-table quote-detail-table"><thead><ScreenViewGroupHeader fields={visibleOrderLineFields}/><tr>{visibleOrderLineFields.map(field=><th key={field.key}>{field.label}</th>)}</tr></thead><tbody>{order.lines.map(line=><tr key={line.lineNumber}>{visibleOrderLineFields.map(field=><td key={field.key}>{field.key==='stockCode'?line.stockCode:field.key==='stockName'?line.stockName:field.key==='quantity'?`${line.quantity.toLocaleString('tr-TR',{maximumFractionDigits:4})} ${line.unitCode}`:field.key==='deliveredQuantity'?line.deliveredQuantity.toLocaleString('tr-TR',{maximumFractionDigits:4}):field.key==='remainingQuantity'?<b>{line.remainingQuantity.toLocaleString('tr-TR',{maximumFractionDigits:4})}</b>:field.key==='reservedQuantity'?line.reservedQuantity>0?`${line.reservedQuantity.toLocaleString('tr-TR',{maximumFractionDigits:4})} · ${line.reservationWarehouseName}`:'':field.key==='unitPrice'?line.unitPrice.toLocaleString('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:4}):line.lineTotal.toLocaleString('tr-TR',{minimumFractionDigits:2})}</td>)}</tr>)}</tbody></AdvancedDataGrid></div>
    <div className="delivery-history-head"><b>İrsaliyeler</b>{order.status==='Open'&&!activeReservation&&<button className="secondary" disabled={busy||warehouses.filter(x=>x.isActive).length===0} onClick={()=>{setReservationWarehouseId(warehouses.find(x=>x.isActive)?.id||'');setReservationRequestId(crypto.randomUUID());setReservationEditor(true)}}>Stok ayır</button>}{order.status==='Open'&&activeReservation&&role==='TenantAdmin'&&<button className="secondary danger-action" disabled={busy} onClick={()=>void releaseOrderReservation()}>Rezervasyonu bırak</button>}{order.status==='Open'&&<button className="primary" disabled={busy||warehouses.length===0||order.lines.every(x=>x.remainingQuantity===0)} onClick={startDelivery}><Plus size={14}/> İrsaliye oluştur</button>}</div>
    {reservationEditor&&<form className="delivery-editor" onSubmit={reserveOrderStock}><label>Rezervasyon deposu<SearchableRecordPicker options={warehouses.filter(x=>x.isActive).map(x=>({id:x.id,label:`${x.code} · ${x.name}`}))} selectedId={reservationWarehouseId} onSelect={setReservationWarehouseId} title="Rezervasyon deposu seçin" placeholder="Depo seçin" searchPlaceholder="Depo kodu veya adıyla ara" emptyMessage="Aramanızla eşleşen aktif depo bulunamadı." required/></label><p className="muted">Siparişin teslim edilmemiş tüm miktarları için yeterli kullanılabilir stok kontrol edilir. Rezervasyon, bu depodan başka çıkış ve transferler için kullanılabilir miktarı azaltır.</p><div className="modal-foot"><span>Bu işlem stok hareketi oluşturmaz.</span><div><button type="button" className="secondary" onClick={()=>setReservationEditor(false)}>Vazgeç</button><button className="primary" disabled={busy||!reservationWarehouseId}>{busy?'Ayrılıyor…':'Stok ayır'}</button></div></div></form>}
    {editor&&<form className="delivery-editor" onSubmit={createDelivery}><div className="form-two"><label>Depo<SearchableRecordPicker options={warehouses.filter(x=>x.isActive).map(x=>({id:x.id,label:`${x.code} · ${x.name}`}))} selectedId={warehouseId} onSelect={value=>{setWarehouseId(value);setDeliveryLocationIds({});void loadDeliveryLocations(value)}} title="Depo seçin" placeholder="Depo seçin" searchPlaceholder="Depo kodu veya adıyla ara" emptyMessage="Aramanızla eşleşen aktif depo bulunamadı." required/></label><label>Sevk tarihi<input type="date" value={deliveryDate} onChange={e=>setDeliveryDate(e.target.value)} required/></label></div>{order.lines.filter(x=>x.remainingQuantity>0).map(line=><div className="delivery-quantity" key={line.lineNumber}><span><b>{line.stockCode}</b><small>{line.stockName} · siparişte kalan {line.remainingQuantity} {line.unitCode}</small></span><select aria-label={`${line.stockCode} teslim birimi`} value={enteredDeliveryUnits[line.lineNumber]||line.unitCode} onChange={e=>setEnteredDeliveryUnits(current=>({...current,[line.lineNumber]:e.target.value}))}><option value={line.unitCode}>{line.unitCode}</option>{(deliveryUnits[line.lineNumber]||[]).filter(x=>x.isActive&&x.unitCode!==line.unitCode).map(x=><option key={x.id} value={x.unitCode}>{x.unitCode}</option>)}</select><input aria-label={`${line.stockCode} teslim miktarı`} type="number" min="0" step="0.0001" value={quantities[line.lineNumber]??'0'} onChange={e=>setQuantities(current=>({...current,[line.lineNumber]:e.target.value}))}/><select aria-label={`${line.stockCode} teslim konumu`} value={deliveryLocationIds[line.lineNumber]||''} disabled={!warehouseId} onChange={e=>setDeliveryLocationIds(current=>({...current,[line.lineNumber]:e.target.value}))}><option value="">Depo düzeyinde</option>{deliveryLocations.map(location=><option key={location.id} value={location.id}>{location.code} · {location.name}</option>)}</select></div>)}<div className="modal-foot"><span>Konum seçimi isteğe bağlıdır; stok, seçilen konum ve depoda doğrulanır.</span><div><button type="button" className="secondary" onClick={()=>setEditor(false)}>Vazgeç</button><button className="primary" disabled={busy||!warehouseId}>{busy?'Kaydediliyor…':'İrsaliye oluştur'}</button></div></div></form>}
    <div className="delivery-list">{loading?<span className="cell-subtitle">İrsaliyeler yükleniyor…</span>:deliveries.length===0?<span className="cell-subtitle">Henüz irsaliye oluşturulmadı.</span>:deliveries.map(item=><div className="delivery-row" key={item.id}><div><b>{item.code}</b><small>{item.deliveryDate.split('-').reverse().join('.')} · {item.warehouseName} · {item.lineCount} satır</small></div><span className={`quote-status ${item.status==='Posted'?'accepted':'rejected'}`}>{item.status==='Posted'?'Sevk edildi':'İptal'}</span>{item.status==='Posted'&&!item.hasSalesInvoice&&<button className="row-action" disabled={busy} onClick={()=>void createInvoice(item)}>Fatura kes</button>}{item.invoiceId&&<button className="row-action" onClick={()=>onInvoiceCreated(item.invoiceId!)}>Faturayı aç</button>}{item.status==='Posted'&&item.invoiceStatus!=='Posted'&&<button className="row-action danger-action" disabled={busy} onClick={()=>void voidDelivery(item)}>İptal et</button>}</div>)}</div>
    <div className="modal-foot"><span>Sipariş tarihi {order.orderDate} · Kaynak teklif {order.quoteCode}</span><div><button className="secondary" onClick={onClose}>Kapat</button></div></div></div></div>
}

function SalesInvoiceTable({invoices,onOpen,onSelect,selectedId,search,fields,token,onInvoiceCreated}:{invoices:SalesInvoiceSummary[];onOpen:(id:string)=>void;onSelect:(id:string)=>void;selectedId:string|null;search:string;fields:BuiltInScreenLayoutField[];token:string;onInvoiceCreated:(id:string)=>Promise<void>}) {
  const [createOpen,setCreateOpen]=useState(false),[deliveries,setDeliveries]=useState<SalesDeliverySummary[]>([]),[deliveryTotal,setDeliveryTotal]=useState(0),[deliveryPage,setDeliveryPage]=useState(1),[deliverySearch,setDeliverySearch]=useState(''),[deliveryLoading,setDeliveryLoading]=useState(false),[deliveryBusyId,setDeliveryBusyId]=useState<string|null>(null),[deliveryError,setDeliveryError]=useState('')
  useEffect(()=>{
    if(!createOpen)return
    let cancelled=false
    const timer=window.setTimeout(()=>{
      setDeliveryLoading(true);setDeliveryError('')
      api<{items:SalesDeliverySummary[];totalCount:number}>(`/api/sales/deliveries/?unbilledOnly=true&q=${encodeURIComponent(deliverySearch.trim())}&page=${deliveryPage}&pageSize=25`,token)
        .then(result=>{if(!cancelled){setDeliveries(result.items);setDeliveryTotal(result.totalCount)}})
        .catch(error=>{if(!cancelled)setDeliveryError((error as Error).message)})
        .finally(()=>{if(!cancelled)setDeliveryLoading(false)})
    },deliverySearch?250:0)
    return()=>{cancelled=true;window.clearTimeout(timer)}
  },[createOpen,deliveryPage,deliverySearch,token])
  async function createFromDelivery(item:SalesDeliverySummary){
    setDeliveryBusyId(item.id);setDeliveryError('')
    try{const invoice=await api<SalesInvoiceSummary>(`/api/sales/deliveries/${item.id}/invoice`,token,{method:'POST'});setCreateOpen(false);setDeliverySearch('');setDeliveryPage(1);await onInvoiceCreated(invoice.id)}
    catch(error){setDeliveryError((error as Error).message)}
    finally{setDeliveryBusyId(null)}
  }
  const visible=invoices.filter(x=>!search||`${x.code} ${x.deliveryCode} ${x.orderCode} ${x.customerName}`.toLocaleLowerCase('tr').includes(search.toLocaleLowerCase('tr')))
  const ordered=fields.filter(field=>field.key==='actions'||field.visible).sort((a,b)=>a.key==='actions'?1:b.key==='actions'?-1:a.position-b.position)
  const render=(item:SalesInvoiceSummary,field:BuiltInScreenLayoutField)=>{
    switch(field.key){
      case 'code':return <span className="customer-code">{item.code}</span>
      case 'deliveryCode':return item.deliveryCode
      case 'orderCode':return item.orderCode
      case 'customerName':return <b className="customer-name">{item.customerName}</b>
      case 'invoiceDate':return item.invoiceDate.split('-').reverse().join('.')
      case 'lineCount':return item.lineCount
      case 'grandTotal':return <b>{item.grandTotal.toLocaleString('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2})} {item.currencyCode}</b>
      case 'status':return <span className={`quote-status ${item.status==='Posted'?'accepted':'rejected'}`}>{item.status==='Posted'?'Kesildi':'İptal'}</span>
      case 'actions':return <button className="row-action" onClick={event=>{event.stopPropagation();onOpen(item.id)}}>Detay</button>
      default:return null
    }
  }
  return <>
    <SalesInvoiceListHeader onCreate={() => { setDeliveryPage(1); setCreateOpen(true) }}/>
    <SalesDocumentGrid
      fields={ordered}
      items={visible}
      selectedId={selectedId}
      loading={false}
      loadingMessage="Faturalar yükleniyor…"
      emptyMessage="Henüz satış faturası yok. İrsaliye detayından fatura oluşturabilirsiniz."
      search={search}
      searchEmptyMessage="Aramanızla eşleşen fatura yok."
      onSelect={id => { onSelect(id); onOpen(id) }}
      renderCell={(field, item) => render(item, field)}
    />
    {createOpen && <SalesInvoiceFromDeliveryDialog
      deliveries={deliveries}
      total={deliveryTotal}
      page={deliveryPage}
      search={deliverySearch}
      loading={deliveryLoading}
      busyDeliveryId={deliveryBusyId}
      error={deliveryError}
      onClose={() => setCreateOpen(false)}
      onSearchChange={value => { setDeliverySearch(value); setDeliveryPage(1) }}
      onPageChange={setDeliveryPage}
      onCreateInvoice={delivery => void createFromDelivery(delivery)}
    />}
  </>

}



function SalesCustomerPopupSelect({customers,selectedId,onSelect}:{customers:SalesCustomer[];selectedId:string;onSelect:(customer:SalesCustomer)=>void}) {
  const [open,setOpen]=useState(false),[query,setQuery]=useState('')
  const selected=customers.find(customer=>customer.id===selectedId)
  const eligible=customers.filter(customer=>customer.isActive&&customer.type!=='Supplier')
  const normalizedQuery=query.trim().toLocaleLowerCase('tr-TR')
  const filtered=eligible.filter(customer=>!normalizedQuery||`${customer.code} ${customer.name}`.toLocaleLowerCase('tr-TR').includes(normalizedQuery))
  const visible=filtered.slice(0,50)
  useEffect(()=>{
    if(!open)return
    const closeOnEscape=(event:KeyboardEvent)=>{if(event.key==='Escape')setOpen(false)}
    document.addEventListener('keydown',closeOnEscape)
    return()=>document.removeEventListener('keydown',closeOnEscape)
  },[open])
  return <>
    <button type="button" className="customer-popup-trigger" aria-haspopup="dialog" aria-expanded={open} onClick={()=>{setQuery('');setOpen(true)}}>
      <span>{selected?`${selected.code} · ${selected.name} (${selected.currencyCode})`:'Müşteri seçin'}</span><ChevronDown size={16}/>
    </button>
    {open&&createPortal(<div className="modal-backdrop customer-picker-backdrop" onMouseDown={event=>{if(event.target===event.currentTarget)setOpen(false)}}>
      <section className="modal customer-picker-modal" role="dialog" aria-modal="true" aria-labelledby="sales-customer-picker-title">
        <div className="modal-head"><div><p className="eyebrow">SATIŞ YÖNETİMİ</p><h2 id="sales-customer-picker-title">Müşteri seçin</h2></div><button type="button" className="icon-button" aria-label="Müşteri seçimini kapat" onClick={()=>setOpen(false)}><X size={19}/></button></div>
        <label className="customer-search"><Search size={15}/><input type="search" autoFocus value={query} onChange={event=>setQuery(event.target.value)} placeholder="Müşteri kodu veya unvanıyla ara"/></label>
        <div className="customer-picker-options" role="listbox" aria-label="Aktif müşteriler">
          {visible.map(customer=><button type="button" role="option" aria-selected={customer.id===selectedId} className="customer-picker-option" key={customer.id} onClick={()=>{onSelect(customer);setOpen(false)}}><span><b>{customer.code} · {customer.name}</b><small>{customer.currencyCode}</small></span>{customer.id===selectedId&&<span className="customer-picker-selected">Seçili</span>}</button>)}
          {filtered.length>visible.length&&<div className="customer-picker-empty">İlk {visible.length} sonuç gösteriliyor. Aramayı daraltın.</div>}
          {filtered.length===0&&<div className="customer-picker-empty">{eligible.length===0?'Seçilebilir aktif müşteri bulunmuyor.':'Aramanızla eşleşen müşteri bulunamadı.'}</div>}
        </div>
      </section>
    </div>,document.body)}
  </>
}
